function d2(a,b){ var s=0; for(var i=0;i<a.length;i++){ var d=a[i]-b[i]; s+=d*d; } return s; }
function buildKd(points, depth){ if(points.length===0) return null; var axis=depth%2; points.sort(function(a,b){return a[axis]-b[axis];}); var mid=Math.floor(points.length/2); var node={point:points[mid], axis:axis, left:null, right:null}; node.left=buildKd(points.slice(0,mid), depth+1); node.right=buildKd(points.slice(mid+1), depth+1); return node; }
function nearest(node, target, best){ if(!node) return best; var dd=d2(node.point, target); if(dd<best.d) best={point:node.point, d:dd}; var diff=target[node.axis]-node.point[node.axis]; var near=diff<0?node.left:node.right; var far=diff<0?node.right:node.left; if(near) best=nearest(near,target,best); if(far && diff*diff<best.d) best=nearest(far,target,best); return best; }
function makeKd(points){ return buildKd(points,0); }
function queryKd(root,target){ var b=nearest(root,target,{point:null,d:Infinity}); return b.point; }
var EXPORTS={makeKd:makeKd, queryKd:queryKd};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KdTreeForgePure = EXPORTS; }
